import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

const phase = atom({ plugin: 'prompt-enhance', key: 'phase' } as const, 'idle')
const SKILLS_DIR = `${process.env.HOME}/.claude/skills`

const SYSTEM = `Você reescreve prompts vagos para um assistente de código (Claude Code). Use as instruções do projeto e as skills disponíveis só para tornar o prompt mais específico (arquivos, convenções, skills relevantes, critérios de pronto). Não invente fatos nem amplie o escopo. Mantenha o idioma do prompt original. Responda APENAS com o prompt melhorado, sem comentários.`

async function enhance($: any) {
  const draft = (await $.prompt.read()).text.trim()
  if (!draft) return $.ui.toast('Escreva um prompt primeiro')
  await update($, phase, () => 'working')
  const root = await $.session.root()
  const instructions = await $.fs.read(`${root}/CLAUDE.md`).catch(() => '')
  const skills = (await $.fs.list(SKILLS_DIR).catch(() => []))
    .filter((f: { kind: string }) => f.kind === 'dir')
    .map((f: { name: string }) => f.name)
    .join(', ')
  const r = await $.model.complete({
    model: 'sonnet',
    system: SYSTEM,
    prompt: `Instruções do projeto (CLAUDE.md):\n${instructions.slice(0, 6000)}\n\nSkills instaladas: ${skills}\n\nPrompt original:\n${draft}`,
  })
  if (r.isAnswered) {
    await $.prompt.fill({ text: r.text.trim(), mode: 'replace' })
    await update($, phase, () => 'ready')
  } else {
    $.ui.toast('Não consegui melhorar o prompt')
    await update($, phase, () => 'idle')
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'melhorar', description: 'Melhora o prompt da caixa; depois clique em Enviar' })

    return next(e)
  })

  on('command.run', { command: 'melhorar' }, async $ => {
    await enhance($)

    return { text: 'Prompt melhorado na caixa. Revise e clique em Enviar.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    const p = await read($, phase)

    return (
      <Box>
        {p === 'working' && <Text dimColor>Melhorando o prompt… </Text>}
        {p !== 'working' && <Button key="enh" label="✨ Melhorar" onPress={() => enhance($)} />}
        {p === 'ready' && (
          <Box>
            <Text> </Text>
            <Button
              key="send"
              label="Enviar"
              onPress={async () => {
                const text = (await $.prompt.read()).text
                await update($, phase, () => 'idle')
                await $.prompt.fill({ text: '', mode: 'replace' })
                void $.prompt.submit({ text })
              }}
            />
          </Box>
        )}
      </Box>
    )
  })
}

